
public class ArrayTest03 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String [] bts = {
				"RM", "제이홉", "정국", "지민", "진", "슈가", "뷔"
		};
		helloBts(bts);
	}

	private static void helloBts(String[] bts) {
		// TODO Auto-generated method stub
		for (String member : bts) System.out.println(member);
	}

}
